/**
 * SpellSuggester
 *
 * "Did you mean" suggestions driven by the index vocabulary and term
 * frequencies. Candidates are generated by single-edit transforms
 * (delete/transpose/replace/insert) — the SymSpell approach — then
 * ranked by frequency and edit distance.
 */

import { InvertedIndex } from '../index/InvertedIndex';
import { levenshtein } from '../index/FuzzyMatch';

export interface SpellSuggestion {
  readonly suggestion: string;
  readonly frequency: number;
  readonly editDistance: number;
  readonly score: number;
}

export interface SpellOptions {
  readonly maxEdits?: number;
  readonly maxSuggestions?: number;
  /** minimum term frequency to be a suggestion candidate */
  readonly minFrequency?: number;
  /** only suggest if the term is OOV or below this frequency */
  readonly onlyIfRareBelow?: number;
}

const ALPHABET = 'abcdefghijklmnopqrstuvwxyz';

/** All strings one edit away from `term`. */
export function edits1(term: string): Set<string> {
  const out = new Set<string>();
  const n = term.length;
  // deletes
  for (let i = 0; i < n; i++) out.add(term.slice(0, i) + term.slice(i + 1));
  // transposes
  for (let i = 0; i < n - 1; i++) {
    out.add(term.slice(0, i) + term[i + 1] + term[i] + term.slice(i + 2));
  }
  // replaces
  for (let i = 0; i < n; i++) {
    for (const c of ALPHABET) {
      if (c !== term[i]) out.add(term.slice(0, i) + c + term.slice(i + 1));
    }
  }
  // inserts
  for (let i = 0; i <= n; i++) {
    for (const c of ALPHABET) {
      out.add(term.slice(0, i) + c + term.slice(i));
    }
  }
  return out;
}

export class SpellSuggester {
  private readonly index: InvertedIndex;
  private readonly termFreq: Map<string, number>;

  constructor(index: InvertedIndex) {
    this.index = index;
    this.termFreq = new Map();
    this.rebuild();
  }

  /** Recompute corpus term frequencies from the index. */
  rebuild(): void {
    this.termFreq.clear();
    for (const term of this.index.vocabulary()) {
      let total = 0;
      for (const p of this.index.postings(term)) total += p.frequency;
      this.termFreq.set(term, total);
    }
  }

  frequency(term: string): number {
    return this.termFreq.get(term) ?? 0;
  }

  /**
   * Suggest corrections for a (possibly misspelled) term. Returns the
   * term itself unchanged if it's already frequent enough.
   */
  suggest(term: string, options: SpellOptions = {}): SpellSuggestion[] {
    const maxEdits = options.maxEdits ?? 2;
    const maxSuggestions = options.maxSuggestions ?? 5;
    const minFreq = options.minFrequency ?? 1;
    const current = this.frequency(term);
    if (options.onlyIfRareBelow !== undefined && current >= options.onlyIfRareBelow) {
      return [{ suggestion: term, frequency: current, editDistance: 0, score: 1 }];
    }
    const candidates = new Map<string, number>(); // term -> edit distance
    let frontier = [term];
    const seen = new Set<string>([term]);
    for (let d = 1; d <= maxEdits; d++) {
      const next: string[] = [];
      for (const w of frontier) {
        for (const e of edits1(w)) {
          if (seen.has(e)) continue;
          seen.add(e);
          const freq = this.frequency(e);
          if (freq >= minFreq) {
            const existing = candidates.get(e);
            if (existing === undefined || d < existing) {
              candidates.set(e, d);
            }
          }
          // continue expanding for deeper edits
          next.push(e);
        }
      }
      frontier = next;
      // prune frontier size for performance
      if (frontier.length > 10_000) frontier.length = 10_000;
    }
    const maxFreq = Math.max(1, ...[...candidates.keys()].map((t) => this.frequency(t)));
    const out: SpellSuggestion[] = [...candidates.entries()].map(([s, d]) => {
      const frequency = this.frequency(s);
      // combine frequency (log-scaled) and edit distance
      const freqScore = Math.log(1 + frequency) / Math.log(1 + maxFreq);
      const distScore = 1 - d / (maxEdits + 1);
      return {
        suggestion: s,
        frequency,
        editDistance: d,
        score: 0.6 * freqScore + 0.4 * distScore,
      };
    });
    out.sort((a, b) => b.score - a.score || a.suggestion.localeCompare(b.suggestion));
    return out.slice(0, maxSuggestions);
  }

  /** Suggest corrections for each term in a query string. */
  suggestQuery(query: string): { original: string; suggestions: SpellSuggestion[] }[] {
    return query
      .toLowerCase()
      .split(/\s+/)
      .filter((s) => s.length > 0)
      .map((t) => ({ original: t, suggestions: this.suggest(t) }));
  }
}

/** Verify suggestion quality with real edit distance (double-check). */
export function verifyEditDistance(a: string, b: string): number {
  return levenshtein(a, b);
}
